UPDATE businesses SET description = 'T & M Electrical and Plumbing is a wholly Black-owned SME based at Unit 308, Wonderpark Estates, 886 First Avenue, Karen Park, Pretoria, formed in 2006. The company offers electrical services including installations and maintenance, geyser installation, household appliance work, prepaid meter installations, electrical connections, generator installations and solar power installations. Its plumbing services cover drainage work, geyser installation and repair, hot and cold-water piping, solar geyser installations and storm-water systems. T & M Electrical and Plumbing serves domestic, residential and commercial customers across Pretoria and the surrounding areas, and is able to undertake projects nationally. The company provides emergency call-out services available 24 hours a day, seven days a week, for both electrical and plumbing issues, giving customers access to urgent repairs outside of normal business hours.', description_enriched_at = datetime('now') WHERE slug = 't-m-electrical-website-karenpark' AND description = 'T & M Electrical is a property-maintenance company in Karenpark, Pretoria, offering electrical, plumbing, property-management and gardening services to clients including law firms, restaurants, residential estates and government facilities.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
